code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    row3 = [3 in row for row in grid]
    col3 = [any(grid[r][c] == 3 for r in range(h)) for c in range(w)]
    horizontal = sum(row3) <= sum(col3)
    out = [[0] * w for _ in range(h)]
    if horizontal:
        cols2 = {c for r in range(h) for c in range(w) if grid[r][c] == 2}
        if any(grid[r][1] == 2 for r in range(h)): cols2.add(0)
        if any(grid[r][-2] == 2 for r in range(h)): cols2.add(w - 1)
        for r in range(h):
            for c in range(w):
                if row3[r]: out[r][c] = 3
                elif c in cols2: out[r][c] = 2 if 2 in grid[r] else frame
    else:
        rows2 = {r for r in range(h) if 2 in grid[r]}
        if 2 in grid[1]: rows2.add(0)
        if 2 in grid[-2]: rows2.add(h - 1)
        for r in range(h):
            for c in range(w):
                if col3[c]: out[r][c] = 3
                elif r in rows2: out[r][c] = 2 if grid[r][c] == 2 else frame
    return out
'''
